-- Generated by tool/scripts/migration/generate_equipment_cube_drops.py.
-- Remove every legacy cube drop before assigning cubes to the current boss tiers.
-- chance uses a 1,000,000 base, so every row below has an independent 10% chance.
DELETE FROM `drop_data`
WHERE `itemid` BETWEEN 4007000 AND 4007007;


-- Keep the migration safe if a target row is restored concurrently during deployment.
-- The preceding DELETE normally means this clause has no rows to update.
ON DUPLICATE KEY UPDATE
    `minimum_quantity` = VALUES(`minimum_quantity`),
    `maximum_quantity` = VALUES(`maximum_quantity`),
    `questid` = VALUES(`questid`),
    `chance` = VALUES(`chance`);
